<script setup>
import {computed,ref,watch} from 'vue';
import {session} from '../../../lib/session';
import {rankReportAgents} from '../../../lib/cc-report-ranking';
import {downloadCsv} from '../../../lib/cc';
import CCDataTable from '../CCDataTable.vue';
const props=defineProps({appointments:{type:Array,default:()=>[]},received:{type:Array,default:()=>[]},names:{type:Object,default:()=>({})},from:String,to:String,restrictedOwner:String});
const targets=ref({}),draft=ref({}),notice=ref('');
const storageKey=owner=>'life-cc-kpi-v1:'+session.user+':'+props.from+':'+props.to+':'+String(owner).toLowerCase();
const owners=computed(()=>[...new Set([...props.appointments,...props.received].map(r=>r.lead_owner).filter(Boolean))]);
watch(()=>[props.from,props.to,owners.value.join('|')],()=>{const next={};for(const owner of owners.value){try{next[owner]=JSON.parse(localStorage.getItem(storageKey(owner))||'{}');}catch{next[owner]={};}}targets.value=next;draft.value=structuredClone(next);notice.value='';},{immediate:true});
const ranked=computed(()=>rankReportAgents(props.appointments,props.received,targets.value,props.restrictedOwner));
const columns=[{key:'rank',label:'Rank'},{key:'agent',label:'Agent',value:r=>props.names[r.agent]||r.agent},{key:'leads',label:'Leads',value:r=>r.leads===null?'Not loaded':r.leads},{key:'visits',label:'Visits'},{key:'booked',label:'Bookings'},{key:'pct',label:'Visit → Booking %',value:r=>r.pct===null?'—':r.pct.toFixed(1)+'%'},{key:'bookingAchievement',label:'Booking Target %',value:r=>r.bookingAchievement===null?'—':r.bookingAchievement.toFixed(1)+'%'},{key:'visitAchievement',label:'Visit Target %',value:r=>r.visitAchievement===null?'—':r.visitAchievement.toFixed(1)+'%'},{key:'score',label:'Final Score',value:r=>r.score===null?'Awaiting KPI inputs':r.score.toFixed(1)}];
function save(){for(const owner of owners.value){const input=draft.value[owner]||{};if(Object.values(input).every(v=>v===''||v===undefined))continue;if(!['bookingTarget','visitTarget','handling','followup'].every(k=>input[k]!==''&&input[k]!==undefined&&Number.isFinite(Number(input[k])))||Number(input.bookingTarget)<=0||Number(input.visitTarget)<=0||['handling','followup'].some(k=>Number(input[k])<0||Number(input[k])>100)){notice.value='Enter positive targets and completion percentages from 0 to 100 for each edited agent.';return;}}
 try{for(const owner of owners.value)localStorage.setItem(storageKey(owner),JSON.stringify(draft.value[owner]||{}));targets.value=JSON.parse(JSON.stringify(draft.value));notice.value='Validated KPI inputs applied in this browser.';}catch{notice.value='Browser storage is unavailable; KPI inputs could not be saved.';}}
</script>
<template><section class="cc-report-summary life-premium-section"><header><h2>🏆 All Agents · KPI Performance Ranking</h2><button @click="downloadCsv('cc-kpi-ranking.csv',columns,ranked)">⬇ Export CSV</button></header><p>Selected report period: {{from}} → {{to}} · ranked by Final Score descending.</p><CCDataTable :columns="columns" :rows="ranked"/><p class="cc-note">Booking achievement 35% + Visit achievement 25% + Conversion 20% + Lead handling 10% + Follow-up completion 10%. Target achievements cap at 100%. Conversion has zero weight for 0–4 visits, half weight for 5–9, and full weight for 10+. Missing inputs remain unranked.</p><details><summary>⚙ KPI targets &amp; completion inputs · this browser only</summary><p>Enter approved targets and actual completion rates. These inputs are not ERP records.</p><form @submit.prevent="save"><div class="cc-table"><table><thead><tr><th>Agent</th><th>Booking target</th><th>Visit target</th><th>Lead handling %</th><th>Follow-up completion %</th></tr></thead><tbody><tr v-for="owner in owners" :key="owner"><th>{{names[owner]||owner}}</th><td v-for="key in ['bookingTarget','visitTarget','handling','followup']" :key="key"><input v-model="draft[owner][key]" type="number" :min="key.includes('Target')?1:0" :max="key.includes('Target')?undefined:100" :step="key.includes('Target')?1:.1" :aria-label="(names[owner]||owner)+' '+key"></td></tr></tbody></table></div><button type="submit">Apply validated KPI inputs</button><p role="status">{{notice}}</p></form></details></section></template>
<style scoped src="../../../styles/cc-agent-report.css"></style>
<style scoped>details{margin-top:12px}input{width:110px;box-sizing:border-box}summary{cursor:pointer;font-weight:700}</style>
